type Identified = { readonly id: string };

function ids(values: readonly Identified[]): string[] {
  return values.map((value) => value.id);
}

function clone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

function nextId(prefix: string, values: readonly Identified[]): string {
  const used = new Set(ids(values));
  let ordinal = values.length + 1;
  while (used.has(`${prefix}-${ordinal}`)) ordinal += 1;
  return `${prefix}-${ordinal}`;
}

function addClone<T extends Identified>(update: EditorUpdate, path: EditorPath, values: readonly T[], prefix: string): void {
  if (values.length === 0) return;
  const next = clone(values[values.length - 1]!);
  (next as { id: string }).id = nextId(prefix, values);
  update(path, [...values, next]);
}

function quantity<D extends QuantityDimension>(value: number, unit: Quantity<D>['unit']): Quantity<D> {
  return { value, unit };
}

function firstUnit(document: VehicleEngineDocument, dimension: QuantityDimension): string {
  return QUANTITY_UNITS[dimension][0];
}

function restrictionFor(type: FlowRestriction['type'], document: VehicleEngineDocument): FlowRestriction {
  if (type === 'orifice') {
    return { type, effective_area: quantity(0, 'm2'), discharge_coefficient_01: 1 };
  }
  if (type === 'curve') {
    return { type, pressure_drop_to_flow: document.engine.curves[0]?.id ?? '' };
  }
  return {
    type,
    rated_flow: { value: 0, unit: 'cfm', standard: 'port_28_inh2o' },
    pressure_drop: quantity(28, 'inH2O'),
  };
}

function RestrictionEditor({ label, restriction, path, document, disabled, update }: {
  readonly label: string;
  readonly restriction: FlowRestriction;
  readonly path: EditorPath;
  readonly document: VehicleEngineDocument;
  readonly disabled: boolean;
  readonly update: EditorUpdate;
}) {
  return <article className={styles.restrictionRow}>
    <strong>{label}</strong>
    <SelectControl label="Model" value={restriction.type} options={['flow_bench', 'orifice', 'curve']} path={[...path, 'type']} disabled={disabled} update={(_ignored, value) => update(path, restrictionFor(value as FlowRestriction['type'], document))} />
    {restriction.type === 'flow_bench' ? <>
      <QuantityControl label="Rated flow" quantity={restriction.rated_flow} path={[...path, 'rated_flow']} disabled={disabled} update={update} />
      <SelectControl label="Calibration standard" value={restriction.rated_flow.standard} options={['carburetor_1p5_inhg', 'port_28_inh2o']} path={[...path, 'rated_flow', 'standard']} disabled={disabled} update={update} />
      <QuantityControl label="Pressure drop" quantity={restriction.pressure_drop} path={[...path, 'pressure_drop']} disabled={disabled} update={update} />
    </> : null}
    {restriction.type === 'orifice' ? <>
      <QuantityControl label="Effective area" quantity={restriction.effective_area} path={[...path, 'effective_area']} disabled={disabled} update={update} />
      <NumberControl label="Discharge coefficient" value={restriction.discharge_coefficient_01} min={0} max={1} path={[...path, 'discharge_coefficient_01']} disabled={disabled} update={update} />
    </> : null}
    {restriction.type === 'curve' ? <div className={styles.wideControl}><SelectControl label="Pressure-to-flow curve" value={restriction.pressure_drop_to_flow} options={ids(document.engine.curves)} searchable path={[...path, 'pressure_drop_to_flow']} disabled={disabled} update={update} /></div> : null}
  </article>;
}

function CurveEditor({ curve, index, document, disabled, update }: {
  readonly curve: CurveDefinition;
  readonly index: number;
  readonly document: VehicleEngineDocument;
  readonly disabled: boolean;
  readonly update: EditorUpdate;
}) {
  const path: EditorPath = ['engine', 'curves', index];
  const addSample = () => {
    const previous = curve.samples[curve.samples.length - 1];
    const inputUnit = previous?.input.unit ?? firstUnit(document, curve.input_dimension);
    const outputUnit = previous?.output.unit ?? firstUnit(document, curve.output_dimension);
    update([...path, 'samples'], [...curve.samples, {
      input: { value: previous?.input.value ?? 0, unit: inputUnit },
      output: { value: previous?.output.value ?? 0, unit: outputUnit },
    }]);
  };
  return <SemanticCard title={curve.id}>
    <FieldGrid columns={4}>
      <TextControl label="Curve ID" value={curve.id} path={[...path, 'id']} disabled={disabled} update={update} />
      <SelectControl label="Input dimension" value={curve.input_dimension} options={Object.keys(QUANTITY_UNITS)} path={[...path, 'input_dimension']} disabled={disabled} update={update} />
      <SelectControl label="Output dimension" value={curve.output_dimension} options={Object.keys(QUANTITY_UNITS)} path={[...path, 'output_dimension']} disabled={disabled} update={update} />
      <SelectControl label="Evaluation" value={curve.evaluation} options={['linear', 'right_continuous_hold', 'triangle_weighted_samples']} path={[...path, 'evaluation']} disabled={disabled} update={update} />
      <SelectControl label="Below range" value={curve.below_domain} options={['clamp', 'zero', 'reject']} path={[...path, 'below_domain']} disabled={disabled} update={update} />
      <SelectControl label="Above range" value={curve.above_domain} options={['clamp', 'zero', 'reject']} path={[...path, 'above_domain']} disabled={disabled} update={update} />
      {curve.triangle_filter_radius ? <QuantityControl label="Smoothing radius" quantity={curve.triangle_filter_radius} path={[...path, 'triangle_filter_radius']} disabled={disabled} update={update} /> : <OptionalControl label="Smoothing radius" purpose="Used by triangle-weighted samples to widen each sample's contribution." disabled={disabled} onAdd={() => update([...path, 'triangle_filter_radius'], { value: 0, unit: firstUnit(document, curve.input_dimension) })} />}
    </FieldGrid>
    <TableWrap><table className={styles.semanticTable}><thead><tr><th>#</th><th>Input</th><th>Output</th></tr></thead><tbody>{curve.samples.map((sample, sampleIndex) => <tr key={`${curve.id}-${sampleIndex}`}><td className={styles.rowName}>{sampleIndex + 1}</td><td><QuantityControl label={`Sample ${sampleIndex + 1} input`} quantity={sample.input} path={[...path, 'samples', sampleIndex, 'input']} disabled={disabled} update={update} /></td><td><QuantityControl label={`Sample ${sampleIndex + 1} output`} quantity={sample.output} path={[...path, 'samples', sampleIndex, 'output']} disabled={disabled} update={update} /></td></tr>)}</tbody></table></TableWrap>
    <div className={styles.inlineAction}><GroupButton disabled={disabled} onClick={addSample}>+ Add sample</GroupButton></div>
  </SemanticCard>;
}

function CurvesGroup({ title, meta, curveIds, document, disabled, update }: {
  readonly title: string;
  readonly meta: string;
  readonly curveIds: ReadonlySet<string>;
  readonly document: VehicleEngineDocument;
  readonly disabled: boolean;
  readonly update: EditorUpdate;
}) {
  const curves = document.engine.curves.map((curve, index) => ({ curve, index })).filter(({ curve }) => curveIds.has(curve.id));
  return <SectionGroup title={title} meta={meta}><div className={styles.cardStack}>{curves.length > 0 ? curves.map(({ curve, index }) => <CurveEditor key={`${curve.id}-${index}`} curve={curve} index={index} document={document} disabled={disabled} update={update} />) : <p className={styles.emptyGroup}>No curve is referenced by this mechanism.</p>}</div></SectionGroup>;
}

export function EngineSection({ document, disabled, update }: EditorSectionProps) {
  const engine = document.engine;
  const usedCurves = new Set<string>();
  for (const port of engine.ports) usedCurves.add(port.flow_curve);
  for (const lobe of engine.cam_lobes) if (lobe.type === 'sampled') usedCurves.add(lobe.lift_curve);
  for (const fuel of engine.fuels) usedCurves.add(fuel.turbulence_to_flame_speed);
  usedCurves.add(engine.ignition.timing_curve);
  const unassigned = new Set(engine.curves.filter((curve) => !usedCurves.has(curve.id)).map((curve) => curve.id));
  return <>
    <div className={styles.mechanismSummary}><span><strong>{engine.cylinders.length}</strong> cylinders</span><span><strong>{engine.banks.length}</strong> banks</span><span><strong>{engine.layout.replaceAll('_', ' ')}</strong> layout</span><span><strong>{engine.limits.redline.value} {engine.limits.redline.unit}</strong> redline</span></div>
    <SectionGroup title="Engine identity" meta="Stable project identity and human-readable metadata"><FieldGrid columns={2}><TextControl label="Engine ID" value={engine.identity.id} path={['engine', 'identity', 'id']} disabled={disabled} update={update} /><TextControl label="Display name" value={engine.identity.display_name} path={['engine', 'identity', 'display_name']} disabled={disabled} update={update} /><div className={styles.fullWidth}><TextControl label="Description" multiline value={engine.identity.description ?? ''} path={['engine', 'identity', 'description']} disabled={disabled} update={update} /></div></FieldGrid></SectionGroup>
    <SectionGroup title="Architecture and operating limit" meta="Cycle and layout constrain every downstream mechanism"><FieldGrid><SelectControl label="Cycle" value={engine.cycle} options={['four_stroke']} path={['engine', 'cycle']} disabled={disabled} update={update} /><SelectControl label="Layout" value={engine.layout} options={['inline', 'v_engine', 'opposed', 'custom']} path={['engine', 'layout']} disabled={disabled} update={update} /><QuantityControl label="Redline" quantity={engine.limits.redline} path={['engine', 'limits', 'redline']} disabled={disabled} update={update} /></FieldGrid></SectionGroup>
    {unassigned.size > 0 ? <CurvesGroup title="Unassigned response curves" meta="Valid definitions not currently consumed by a mechanism" curveIds={unassigned} document={document} disabled={disabled} update={update} /> : null}
  </>;
}

