function journalVariant(journal: JournalDefinition, type: JournalDefinition['type'], document: VehicleEngineDocument): JournalDefinition {
  if (type === 'master_rod') return { id: journal.id, type, master_cylinder: document.engine.cylinders[0]?.id ?? '', throw_radius: quantity(0, 'mm'), phase: clone(journal.phase) };
  return { id: journal.id, type, crankshaft: document.engine.crankshafts[0]?.id ?? '', phase: clone(journal.phase) };
}

