function exhaustGeometry(exhaust: ExhaustDefinition, mode: 'length' | 'volume'): ExhaustDefinition {
  const next = clone(exhaust);
  if (mode === 'length') {
    next.collector_length = next.collector_length ?? quantity(0, 'm');
    delete next.collector_volume;
  } else {
    next.collector_volume = next.collector_volume ?? quantity(0, 'L');
    delete next.collector_length;
  }
  return next;
}

